nt&amp;source=gmail&amp;ust=1792438294793000&amp;usg=AOvVaw0cbWBM9p3y8hFdW9TuQpQP">rep.int</a>(1, n))<br>10: model.spmatrix(t, data, transpose = transpose, drop.unused.levels = drop.unused.levels,     row.names = row.names, sep = sep, verbose = verbose)<br>11: sparse.model.matrix(object, data = data, contrasts.arg = contrasts.arg,     drop.unused.levels = drop.unused.levels, xlev = xlev, ...)<br>12: MatrixModels::model.Matrix(new.fix.formula, data = model.frame(new.fix.formula,     data.same.len, na.action = inla.na.action), contrasts.arg = contrasts,     sparse = TRUE)<br>13: inla.core(formula = formula, family = family, contrasts = contrasts,     data = data, quantiles = quantiles, E = E, offset = offset,     scale = scale, weights = weights, Ntrials = Ntrials, strata = strata,     lp.scale = lp.scale, link.covariates = link.covariates, verbose = verbose,     lincomb = lincomb, selection = selection, control.compute = control.compute,     control.predictor = control.predictor, control.family = control.family,     control.inla = control.inla, control.fixed = control.fixed,     control.mode = control.mode, control.expert = control.expert,     control.hazard = control.hazard, control.lincomb = control.lincomb,     control.update = control.update, control.lp.scale = control.lp.scale,     control.pardiso = control.pardiso, only.hyperparam = only.hyperparam,     inla.call = inla.call, inla.arg = inla.arg, num.threads = num.threads,     blas.num.threads = blas.num.threads, keep = keep, working.directory = working.directory,     silent = silent, inla.mode = inla.mode, safe = FALSE, debug = debug,     .parent.frame = .parent.frame)<br>14: doTryCatch(return(expr), name, parentenv, handler)<br>15: tryCatchOne(expr, names, parentenv, handlers[[1L]])<br>16: tryCatchList(expr, classes, parentenv, handlers)<br>17: tryCatch(expr, error = function(e) {    call &lt;- conditionCall(e)    if (!is.null(call)) {        if (identical(call[[1L]], quote(doTryCatch)))             call &lt;